  ui_story_5055_50550502_19_dialog_content = "¡Tengo que ser más útil y cuidar de mi casa!",
  ui_story_5055_50550601_1_dialog_content = "El Desierto de Rediesel es genial, excepto por la escasez de agua. Es difícil que las plantas normales crezcan aquí.",
  ui_story_5055_50550601_2_dialog_content = "Mi maestro dijo que algunos prados y bosques tienen miles de años de antigüedad fuera del desierto, ¡así como océanos con arrecifes y algas marinas!",
