  ui_story_5055_50550601_13_dialog_content = "<color=#e8d9bb>Eve tropieza con algo, perdiendo el equilibrio y cayendo al suelo.</color>",
  ui_story_5055_50550601_14_dialog_content = "Tú...",
  ui_story_5055_50550601_15_dialog_content = "(¡Es esa muñeca de nuevo! ¿Pero no la derroté? ¿Cómo salió del pozo?)",
  ui_story_5055_50550601_16_dialog_content = "(Afortunadamente, la caída en realidad me salvó de acercarme más al pozo, o me habría sorprendido.)",
