  ui_story_5055_50550601_21_dialog_content = "¡Oh no, no podemos dejar que siga invocando a los Eclipsites!",
  ui_story_5055_50550602_1_dialog_content = "Uf, eso fue difícil... Pero podría aparecer en otro lugar de nuevo.",
