  ui_story_5055_50550702_17_dialog_content = "Uhh...",
  ui_story_5055_50550702_18_dialog_content = "¡Jajaja! El perro que nadie pudo domesticar, pero tú lograste controlarlo. Realmente eres algo especial, Eve!",
  ui_story_5055_50550702_19_dialog_content = "Los animales rara vez atacan si no los amenazamos primero.",
  ui_story_5055_50550702_20_dialog_content = "El cachorro puede sentirlo si no le queremos hacer daño.",
  ui_story_5055_50550702_21_dialog_content = "No dependía de ello si debía someterse a las modificaciones...",
  ui_story_5055_50550702_22_dialog_content = "Probablemente actuó de manera agresiva porque intentaba protegerse a sí mismo y a la manada.",
  ui_story_5055_50550702_23_dialog_content = "*lloriquea*...",
  ui_story_5055_50550702_24_dialog_content = "Jajaja, me hace cosquillas cuando lames mi mano así...",
  ui_story_5055_50550702_25_dialog_content = "Mira, es un perro amable y sabe lo que estamos diciendo!",
