  ui_story_5055_50550702_27_dialog_content = "Le contaré a todos sobre esto de inmediato para que no lo dañen accidentalmente.",
  ui_story_5055_50550702_28_dialog_content = "Está bien, perrito, estás a salvo ahora. Nadie intentará echarte.",
  ui_story_5055_50550702_29_dialog_content = "Pero tienes que prometerme no hacerle daño a nadie.",
  ui_story_5055_50550702_30_dialog_content = "Mmm, puedes saber en qué casa vivo por el olor, ¿cierto?",
  ui_story_5055_50550702_31_dialog_content = "Si no puedes encontrar algo para comer, ven a verme, ¿vale?",
  ui_story_5055_50550702_32_dialog_content = "¡Guau!",
  ui_story_5055_50550702_33_dialog_content = "Vaya, voy a llegar tarde a la cita de seguimiento con el médico...",
  ui_story_5055_50550702_34_dialog_content = "Vale, tú solo relájate y nos vemos pronto!",
  ui_story_5055_50550702_35_dialog_content = "*gemido*",
  ui_story_5055_50550702_36_dialog_content = "Oye, ¿por qué te aferras a mi zapato como si no quisieras que me vaya?",
  ui_story_5055_50550702_37_dialog_content = "*gemido y ladrido*",
  ui_story_5055_50550702_38_dialog_content = "Vale, vale, realmente tengo algo muy importante que hacer ahora mismo.",
  ui_story_5055_50550702_39_dialog_content = "Te prometo que volveré por ti y hasta podemos patrullar juntos.",
  ui_story_5055_50550702_40_dialog_content = "*sigue sollozando*",
  ui_story_5055_50550801_1_dialog_content = "(Qué pobre perrito era. Probablemente nadie quería acercarse antes, o no sería tan pegajoso.)",
  ui_story_5055_50550801_2_dialog_content = "(No esperaría allí atrás por mí, y no puedo llevarlo al médico...)",
  ui_story_5055_50550801_3_dialog_content = "(Así que tuve que tomar el camino largo para perderlo.)",
  ui_story_5055_50550801_4_dialog_content = "(Me siento mal por ello, pero tiene un olfato agudo y probablemente nos alcanzará pronto.)",
  ui_story_5055_50550801_5_dialog_content = "(Debo terminar el chequeo de salud antes de eso.)",
  ui_story_5055_50550801_6_dialog_content = "¡No! ¡Ayuda!",
  ui_story_5055_50550801_7_dialog_content = "¡La clínica del doctor está en llamas! ¡Necesitamos ayuda! ¡Ahora!",
  ui_story_5055_50550801_8_dialog_content = "¡¿Qué?!",
  ui_story_5055_50550801_9_dialog_content = "Doctor, profesor, ¿dónde estás?",
  ui_story_5055_50550801_10_dialog_content = "<size=45>¿Doctor? ¿Profesor? ¿Puedes oírme?</size>",
  ui_story_5055_50550801_11_dialog_content = "¡Alguien ayúdenos!",
  ui_story_5055_50550801_12_dialog_content = "¡Alguien sigue adentro!",
  ui_story_5055_50550801_13_dialog_content = "¡Tengo que entrar!",
  ui_story_5055_50550801_14_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5055_50550801_15_dialog_content = "... ¡Por favor! ¡Alguien!",
  ui_story_5055_50550801_16_dialog_content = "Profesor, soy yo, Eve! ¿Dónde estás?",
  ui_story_5055_50550801_17_dialog_content = "...",
  ui_story_5055_50550801_18_dialog_content = "¿Qué? ¿También está aquí?",
  ui_story_5055_50550802_1_dialog_content = "¿Está bien, señor?",
  ui_story_5055_50550802_2_dialog_content = "¡N-No te acerques más!",
  ui_story_5055_50550802_3_dialog_content = "¿Señor? Soy yo, Eve, estoy aquí para sacarlo.",
  ui_story_5055_50550802_4_dialog_content = "No... ¡Ayuda! ¡Ayuda!",
  ui_story_5055_50550802_5_dialog_content = "Mi maestro nunca había entrado en pánico así antes... Debe haberse asustado por ese oso de peluche.",
  ui_story_5055_50550802_6_dialog_content = "¿Y dónde está el doctor...?",
  ui_story_5055_50550802_7_dialog_content = "¡Fue toda su idea! ¡No mía! ¡NO MÍA!",
  ui_story_5055_50550802_8_dialog_content = "Por favor, no me hagas daño—!",
  ui_story_5055_50550802_9_dialog_content = "Tómelo con calma, señor. Soy Eve, su estudiante. ¡Nunca le haría daño!",
  ui_story_5055_50550802_10_dialog_content = "¿Alguien intentaba lastimarte? ¿Esa persona también prendió fuego a la clínica?",
  ui_story_5055_50550802_11_dialog_content = "Fue tú...",
  ui_story_5055_50550802_12_dialog_content = "¿Ah?",
  ui_story_5055_50550802_13_dialog_content = "¡Fue tú, monstruo, quien prendió fuego a este lugar!",
  ui_story_5055_50550802_14_dialog_content = "¿Qué...?",
  ui_story_5055_50550802_15_dialog_content = "<color=#e8d9bb>*chasquidos y crepitaciones*</color>",
  ui_story_5055_50550802_16_dialog_content = "(Fuego... Hace tanto calor...)",
  ui_story_5055_50550802_17_dialog_content = "(¿Dónde he visto esto... antes...)",
  ui_story_5055_50550802_18_dialog_content = "(Lo mismo... fuego...)",
  ui_story_5055_50550802_19_dialog_content = "(El techo se está cayendo... Evetodo está cantado a nuestro alrededor... Demasiado humo para respirar...)",
  ui_story_5055_50550802_20_dialog_content = "(Hay alguien... en el fuego...)",
  ui_story_5055_50550802_21_dialog_content = "(Alguien que nunca olvidaré...)",
  ui_story_5055_50550802_22_dialog_content = "(Ella está...)",
  ui_story_5055_50550802_23_dialog_content = "(¡Ella es...!)",
  ui_story_5055_50550802_24_dialog_content = "¡Eres tú! No puedo creer que hayas regresado.",
  ui_story_5055_50550802_25_dialog_content = "Estoy aquí para salvarte, Doctor...",
  ui_story_5055_50550802_26_dialog_content = "¿Fuiste tú quien prendió fuego a este lugar y arruinó todo lo que trabajé tan duro para construir?",
  ui_story_5055_50550802_27_dialog_content = "No...",
  ui_story_5055_50550802_28_dialog_content = "Te otorgué mejores poderes, pero ¿qué has hecho? ¡Mira el desastre que has causado!",
  ui_story_5055_50550802_29_dialog_content = "Mi investigación, mis datos, todo lo que he construido durante todos estos años... e incluso este mismo cuerpo, todo consumido por las llamas.",
  ui_story_5055_50550802_30_dialog_content = "Dime, Eve—¡el pecado de destruirme! ¿Qué vas a pagar por eso?",
  ui_story_5055_50550802_31_dialog_content = "<color=#e8d9bb>¡Boom! *Chisporrotea*</color>",
  ui_story_5055_50550802_32_dialog_content = "¡No soy yo, no soy yo!",
  ui_story_5055_50550802_33_dialog_content = "Fuego...! Pero recuerdo el fuego, ardiendo como un odio eterno...",
  ui_story_5055_50550802_34_dialog_content = "¿Por qué ocurrió el fuego, por qué habría odio en mí?",
  ui_story_5055_50550802_35_dialog_content = "Solo vine aquí para hacer un seguimiento...",
  ui_story_5055_50550802_36_dialog_content = "No quiero lastimar a nadie... ¡Solo quiero ser el Eve que protege a todos!",
  ui_story_5055_50550802_37_dialog_content = "Jejeje... ¡Jajajaja!",
  ui_story_5055_50550802_38_dialog_content = "¿No tienes valor para admitirlo, eh? ¿No eras tú el autoproclamado perfecto angelito?",
  ui_story_5055_50550802_39_dialog_content = "¡Está bien, tú serás enterrado junto con mis datos de investigación!",
  ui_story_5055_50550802_40_dialog_content = "¡Guau!",
  ui_story_5055_50550802_41_dialog_content = "¿El perrito rojo?",
  ui_story_5055_50550802_42_dialog_content = "No, no te acerques... Es demasiado peligroso, ¡mantente alejado!",
  ui_story_5055_50550802_43_dialog_content = "¡Guau-guau!",
  ui_story_5055_50550802_44_dialog_content = "Jajaja, ¿otro que no puede esperar para encontrar su perdición, eh?",
  ui_story_5055_50550802_45_dialog_content = "¡Está bien! ¡Tráelo! Estoy ansioso por probar esta daga.",
  ui_story_5055_50550802_46_dialog_content = "Awoo!!!",
  ui_story_5055_50550802_47_dialog_content = "¡¿Qué?!",
  ui_story_5055_50550802_48_dialog_content = "El edificio se está derrumbando... ¡Cuidado!",
  ui_story_5055_50550802_49_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5055_50550802_50_dialog_content = "(¿Estoy enterrado bajo el edificio colapsado?)",
  ui_story_5055_50550802_51_dialog_content = "(No escuches al doctor y al perro, solo el ruido de las llamas devorando todo.)",
  ui_story_5055_50550802_52_dialog_content = "Pero aún respiro...",
  ui_story_5055_50550802_53_dialog_content = "¿Que todavía estoy vivo?",
  ui_story_5055_50550802_54_dialog_content = "¿De dónde vinieron estas enredaderas y por qué estaban a mi alrededor?",
  ui_story_5055_50550802_55_dialog_content = "Hay un aroma diferente al quemado. En realidad, es distinto y encantador.",
  ui_story_5055_50550802_56_dialog_content = "Es un aroma agradable... Huele como... ¿flores?",
  ui_story_5055_50550802_57_dialog_content = "Ahora recuerdo. ¡Las cosas blancas, delgadas y delicadas fuera de las enredaderas son flores!",
  ui_story_5055_50550802_58_dialog_content = "¿Eres tú, la hierba con tumores en mi bolsillo?",
  ui_story_5055_50550802_59_dialog_content = "Esa bombilla blanca no era un tumor sino un brote... ¿Cómo es que no lo reconocí?",
  ui_story_5055_50550802_60_dialog_content = "Gracias por salvarme de nuevo.",
  ui_story_5055_50550802_61_dialog_content = "Pero ¿qué pasa con el profesor, el doctor y el cachorro rojo...?",
  ui_story_5055_50550802_62_dialog_content = "¿Fue por mí...?",
  ui_story_5055_50550802_63_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_5055_50550802_64_dialog_content = "Césped, ¡no! No me dejes... No...",
  ui_story_5055_50550802_65_dialog_content = "Tonto, ¿por qué te sacrificarías para salvarme del fuego en llamas y del edificio derrumbándose?",
  ui_story_5055_50550802_66_dialog_content = "Si te quedaras en mi bolsillo, probablemente lo lograrías y echarías raíces en el suelo ceniciento...",
  ui_story_5055_50550802_67_dialog_content = "¿Realmente valgo la pena del sacrificio?",
  ui_story_5055_50550802_68_dialog_content = "...",
  ui_story_5055_50550802_69_dialog_content = "¿Quién está ahí?",
  ui_story_5055_50550802_70_dialog_content = "?!!",
  ui_story_5055_50550802_71_dialog_content = "¿Fuiste tú quien prendió fuego a este lugar y arruinó todo lo que trabajé tan duro para construir?",
  ui_story_5055_50550802_72_dialog_content = "¡Fue tú, monstruo, quien prendió fuego a este lugar!",
  ui_story_5055_50550802_73_dialog_content = "¿Acaso tú... encendiste el fuego?",
  ui_story_5055_50550802_74_dialog_content = "Sí.",
  ui_story_5055_50550802_75_dialog_content = "¿Quién eres? ¿Cómo es que te pareces a mí?",
  ui_story_5055_50550802_76_dialog_content = "Soy tú.",
  ui_story_5055_50550802_77_dialog_content = "Soy el dolor que ocultaste, el miedo que no pudiste enfrentar, el recuerdo que te negaste a recordar.",
  ui_story_5055_50550802_78_dialog_content = "Estoy aquí para decirte que no ignores...",
  ui_story_5055_50550802_79_dialog_content = "No ignores la realidad.",
  ui_story_5055_50551102_1_dialog_content = "Nunca supe que había un lugar así en Tail Street.",
  ui_story_5055_50551102_2_dialog_content = "¿Qué?",
  ui_story_5055_50551102_3_dialog_content = "Ahí... ¿Por qué esa chica está retenida ahí?",
  ui_story_5055_50551102_4_dialog_content = "Tantos tubos e instrumentos conectados a su cuerpo... ¡Qué pobre cosa! ¿No hay alguien que la salve?",
  ui_story_5055_50551102_5_dialog_content = "Eso no es una celda, sino una sala de tratamiento para mantenerla a ella y a todos a su alrededor seguros.",
  ui_story_5055_50551102_6_dialog_content = "¿Sala de tratamiento? ¡Y veo un oso de peluche adentro!",
  ui_story_5055_50551102_7_dialog_content = "Es su juguete favorito y compañero más leal.",
  ui_story_5055_50551102_8_dialog_content = "En cuanto a la chica, nadie la conoce mejor que tú.",
  ui_story_5055_50551102_9_dialog_content = "¿La conozco? Parece tan débil, insípida y su cara...",
  ui_story_5055_50551102_10_dialog_content = "¡Parece igual al tuyo!",
  ui_story_5055_50551102_11_dialog_content = "¡Y el mío también!",
  ui_story_5055_50551102_12_dialog_content = "Esa es la verdadera Eve, la Eve en el mundo real.",
  ui_story_5055_50551102_13_dialog_content = "¿El verdadero Eve? ¿Quieres decir que tú y yo somos falsos?",
  ui_story_5055_50551102_14_dialog_content = "No somos falsos. Lo falso es el mundo en el que estamos ahora mismo.",
  ui_story_5055_50551102_15_dialog_content = "Este es el mundo falso que el doctor creó para nosotros a través del hipnotismo, un mundo de falsa felicidad.",
  ui_story_5055_50551102_16_dialog_content = "Nos engañó desde el comienzo. Nunca quiso tratarnos.",
  ui_story_5055_50551102_17_dialog_content = "Ella eliminó las personalidades excesivas en nuestra memoria que podrían amenazar su experimento.",
  ui_story_5055_50551102_18_dialog_content = "Luego ella reescribió la historia para nosotros, donde nuestros padres están vivos, estamos sanados, saludables y vivimos felices para siempre.",
  ui_story_5055_50551102_19_dialog_content = "Todos para mantenernos cuerdos mientras ella realizaba todo tipo de experimentos inmorales en nosotros.",
  ui_story_5055_50551102_20_dialog_content = "...",
  ui_story_5055_50551102_21_dialog_content = "EveAunque dejamos al doctor atrás eventualmente...",
  ui_story_5055_50551102_22_dialog_content = "Este mundo aún nos controla, impidiéndonos ver el mundo real.",
  ui_story_5055_50551102_23_dialog_content = "Estoy muy feliz viviendo en este mundo... ¿Entonces incluso la alegría no es real?",
  ui_story_5055_50551102_24_dialog_content = "Sé que has olvidado tu pasado insoportable, y eso es algo bueno desde ciertos puntos de vista.",
  ui_story_5055_50551102_25_dialog_content = "Pero no puedes quedarte aquí. Debemos regresar al mundo real.",
  ui_story_5055_50551102_26_dialog_content = "¿Volver...?",
  ui_story_5055_50551102_27_dialog_content = "Pero no quiero. Solo quiero dibujar, regar el césped, patrullar fuera del pueblo y proteger a todos...",
  ui_story_5055_50551102_28_dialog_content = "¿Por qué encerrarme así? No lo quiero, ¡no lo quiero!",
  ui_story_5055_50551102_29_dialog_content = "¡Pero debes quedarte ahí o destruirás todo!",
  ui_story_5055_50551102_30_dialog_content = "¿Quieres una repetición de la tragedia que ocurrió en tu ciudad natal?",
  ui_story_5055_50551102_31_dialog_content = "Tragedia, ¿ciudad natal? ¿Qué quieres decir?",
  ui_story_5055_50551102_32_dialog_content = "¿Quieres ver a tus seres queridos lastimados por ti de nuevo?",
  ui_story_5055_50551102_33_dialog_content = "Hermano, y Dawn.",
  ui_story_5055_50551102_34_dialog_content = "¿Hermano? ¿Tengo un hermano? Dawn...?",
  ui_story_5055_50551102_35_dialog_content = "Ugh, ¡me duele la cabeza de nuevo!",
  ui_story_5055_50551102_36_dialog_content = "Veo que aún no puedes recordar.",
  ui_story_5055_50551102_37_dialog_content = "A diferencia de ti, nunca me adapté a este mundo, así que aún recuerdo todo lo que vivimos.",
  ui_story_5055_50551102_38_dialog_content = "Son todo lo que tenemos.",
  ui_story_5055_50551102_39_dialog_content = "Pero estamos atrapados en este mundo falso, incapaces de ver a aquellos que realmente nos amaron.",
  ui_story_5055_50551102_40_dialog_content = "Así que odio al doctor que los borró... ¡Y también te odio a ti!",
  ui_story_5055_50551102_41_dialog_content = "Odio que hayas olvidado que alguna vez existieron y aceptado esta falsa realidad en completa ignorancia.",
  ui_story_5055_50551102_42_dialog_content = "!!!",
  ui_story_5055_50551102_43_dialog_content = "Veo que tengo que hacerte recordar todo para convencerte.",
  ui_story_5055_50551102_44_dialog_content = "Bueno, sígueme a nuestra ciudad natal entonces.",
  ui_story_5055_50551102_45_dialog_content = "El que destruimos con nuestras propias manos.",
  ui_story_5055_50551102_46_dialog_content = "Ciudad natal... Pero, ¿no es esto?",
  ui_story_5055_50551102_47_dialog_content = "Sígueme.",
  ui_story_5055_50551301_1_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5055_50551301_2_dialog_content = "Oye, ¿acaba de hacer erupción un volcán?",
  ui_story_5055_50551301_3_dialog_content = "Lo caliente que rueda por todo el suelo es lava, ¿cierto?",
  ui_story_5055_50551301_4_dialog_content = "Puedo sentir una ola de calor tras otra, incluso desde aquí.",
  ui_story_5055_50551301_5_dialog_content = "¿Seguimos yendo?",
  ui_story_5055_50551301_6_dialog_content = "Casi hemos llegado, nuestra casa.",
  ui_story_5055_50551301_7_dialog_content = "¿Nuestra casa está dentro del volcán?",
  ui_story_5055_50551301_8_dialog_content = "Te esperaré por ahí.",
  ui_story_5055_50551301_9_dialog_content = "¡Oye, espérame!",
  ui_story_5055_50551301_10_dialog_content = "Graah!!",
  ui_story_5055_50551301_11_dialog_content = "¿Hay Eclipsites incluso en un ambiente tan hostil?",
  ui_story_5055_50551301_12_dialog_content = "Estos Eclipsites... Me están recordando algo...",
  ui_story_5055_50551301_13_dialog_content = "El día en que invadieron el pueblo y lo arrasaron hasta el suelo...",
  ui_story_5055_50551301_14_dialog_content = "Y el día en que obtuve el poder monstruoso y me desaté como ellos lo hicieron.",
  ui_story_5055_50551301_15_dialog_content = "El Darkflow entró en mi cuerpo a través de una pequeña semilla...",
  ui_story_5055_50551301_16_dialog_content = "Sentí calor y entumecimiento por dentro, como cien estrellas explotando en silencio.",
  ui_story_5055_50551301_17_dialog_content = "¡Quería perder ese poder atormentador solo para darme cuenta de que me levantó del suelo!",
  ui_story_5055_50551301_18_dialog_content = "Me asusté cuando floté en el aire. Todo lo que quería era agarrar y sujetarme a algo.",
  ui_story_5055_50551301_19_dialog_content = "Terminé agarrando corriente telúrica.",
  ui_story_5055_50551301_20_dialog_content = "Interrumpí el campo magnético, inyecté energía en la corteza, hice que el volcán entrara en erupción y convertí la casa en esto...",
  ui_story_5055_50551301_21_dialog_content = "¡El poder monstruoso me esclavizó en mi momento más débil e indefenso!",
  ui_story_5055_50551301_22_dialog_content = "Perdí toda razón como ellos y destruí todo sin remordimientos...",
  ui_story_5055_50551301_23_dialog_content = "¿Merezco seguir viviendo así?",
  ui_story_5055_50551402_1_dialog_content = "Huff, huff...",
  ui_story_5055_50551402_2_dialog_content = "Se está volviendo más difícil... y más difícil... respirar...",
  ui_story_5055_50551402_3_dialog_content = "¿Por qué tengo que... luchar contra Eclipsites bajo esta condición...?",
  ui_story_5055_50551402_4_dialog_content = "No estoy tan lejos como para no poder volver.",
  ui_story_5055_50551402_5_dialog_content = "Pero...",
  ui_story_5055_50551402_6_dialog_content = "¿Debo regresar?",
  ui_story_5055_50551402_7_dialog_content = "EveEn esta feliz línea de tiempo ha sido destrozada por las llamas.",
  ui_story_5055_50551402_8_dialog_content = "Ese otro yo dijo que nadie esperaba que yo fuera un excelente guerrero en realidad.",
  ui_story_5055_50551402_9_dialog_content = "La doctora solo estaba usando mi cuerpo, pero desaté una venganza desenfrenada sobre ella.",
  ui_story_5055_50551402_10_dialog_content = "¿Es esta la perspectiva a la que debo enfrentarme?",
  ui_story_5055_50551402_11_dialog_content = "Regresando a una desafortunada realidad, llena de odio y dolor, soportando la soledad y el tormento del confinamiento.",
  ui_story_5055_50551402_12_dialog_content = "¿Y si pierdo el control de nuevo...?",
  ui_story_5055_50551402_13_dialog_content = "Podría lastimar a más personas y convertir el entorno en un infierno como esto...",
  ui_story_5055_50551402_14_dialog_content = "No, definitivamente no puedo permitir que eso ocurra.",
  ui_story_5055_50551402_15_dialog_content = "Si esa es su verdadera naturaleza, ¡debo evitarlo de alguna manera!",
  ui_story_5055_50551801_1_dialog_content = "Huff, huff...",
  ui_story_5055_50551801_2_dialog_content = "Aquí estás. Este es nuestro pueblo natal...",
  ui_story_5055_50551801_3_dialog_content = "Cañón del Ojo Rojo.",
  ui_story_5055_50551801_4_dialog_content = "Por fin, tú recordaste.",
  ui_story_5055_50551801_5_dialog_content = "Tan pronto como puse un pie aquí, el pasado volvió a mí en fragmentos burbujeantes, apareciendo uno por uno en mi mente.",
  ui_story_5055_50551801_6_dialog_content = "Finalmente me di cuenta de que esas aterradoras imágenes que me llegaban eran todas reales.",
  ui_story_5055_50551801_7_dialog_content = "Este fue una vez un asentamiento autosuficiente, pero ahora solo quedan rocas sueltas y tierras carbonizadas...",
  ui_story_5055_50551801_8_dialog_content = "Erupción de lava, cenizas cubriendo todo, tierra quebrada... Todo por culpa mía.",
  ui_story_5055_50551801_9_dialog_content = "Todo es así por mi culpa.",
  ui_story_5055_50551801_10_dialog_content = "Maytal vez sea mejor para mí quedarme aquí para siempre.",
  ui_story_5055_50551801_11_dialog_content = "...",
  ui_story_5055_50551801_12_dialog_content = "¿Quieres que regrese al mundo real, cierto?",
  ui_story_5055_50551801_13_dialog_content = "Pero también sabes que probablemente causaré más problemas para quienes me rodean.",
  ui_story_5055_50551801_14_dialog_content = "Entonces, ¿es mejor que me quede? De esa manera, el verdadero yo nunca despertará y nunca perderá el control...",
  ui_story_5055_50551801_15_dialog_content = "Si no regresamos, no hay posibilidad de salir de la sala de tratamiento.",
  ui_story_5055_50551801_16_dialog_content = "Pero no puedo controlarme...",
  ui_story_5055_50551801_17_dialog_content = "No en el pasado, no ahora, y probablemente tampoco en el futuro...",
  ui_story_5055_50551801_18_dialog_content = "Puedo aceptar la impotencia y soportar esos recuerdos horribles...",
  ui_story_5055_50551801_19_dialog_content = "¡Pero no puedo permitir que las personas que me amaron salgan lastimadas una y otra vez!",
  ui_story_5055_50551801_20_dialog_content = "Si te rindes, eso aún lastimará a aquellos que nos amaron.",
  ui_story_5055_50551801_21_dialog_content = "Debemos regresar.",
  ui_story_5055_50551801_22_dialog_content = "Es aún más difícil enfrentar la dura realidad después de despertar de un dulce sueño.",
  ui_story_5055_50551801_23_dialog_content = "No tengo lo necesario para soportar todo ese impacto de una vez...",
  ui_story_5055_50551801_24_dialog_content = "Pero debo agradecerte por decirme mi verdadera realidad y hacerme saber que aún hay personas que me aman genuinamente.",
  ui_story_5055_50551801_25_dialog_content = "Pero yo... simplemente no puedo regresar contigo.",
  ui_story_5055_50551801_26_dialog_content = "Sí, tú puedes. Nosotros podemos.",
  ui_story_5055_50551801_27_dialog_content = "Si eso es lo que insistes, mi única elección es...",
  ui_story_5055_50551801_28_dialog_content = "¡Para destruirte!",
  ui_story_5055_50551801_29_dialog_content = "Eres la única llave para que yo pueda regresar a la realidad. Puedo encerrarme aquí para siempre si me deshago de ti.",
  ui_story_5055_50551801_30_dialog_content = "Mátame y nunca volverás a ver a aquellos que nos aman.",
  ui_story_5055_50551801_31_dialog_content = "Aunque mi hermano, Dawn, y otros no están aquí, todo está bien. No necesito a nadie.",
  ui_story_5055_50551801_32_dialog_content = "Estoy listo para estar solo.",
  ui_story_5055_50551801_33_dialog_content = "Eso es mucho mejor que perder la razón y destruir todo lo que amo con mis propias manos...",
  ui_story_5055_50551801_34_dialog_content = "Una amenaza peligrosa como yo debería permanecer dormida y no despertar.",
  ui_story_5055_50551801_35_dialog_content = "Sé que lo dices con buena intención. Gracias, pero lo siento.",
  ui_story_5055_50551801_36_dialog_content = "Debo matarte.",
  ui_story_5055_50551801_37_dialog_content = "Soy tú. Perderás tu poder al matarme, y en realidad probablemente morirás.",
  ui_story_5055_50551801_38_dialog_content = "¿En serio? Pero, ¿no es aún mejor?",
  ui_story_5055_50551801_39_dialog_content = "Me he cansado mucho de esto...",
  ui_story_5055_50551801_40_dialog_content = "Ahora, terminémoslo.",
  ui_story_5055_50551802_1_dialog_content = "Terminarlo, terminar todo.",
  ui_story_5055_50551802_2_dialog_content = "La lava dejó de fluir. El humo negro se detuvo en el aire. Even los Eclipsitas cercanos se detuvieron...",
  ui_story_5055_50551802_3_dialog_content = "Hay tanto silencio.",
  ui_story_5055_50551802_4_dialog_content = "Suficiente para escuchar mi latido del corazón.",
  ui_story_5055_50551802_5_dialog_content = "Pero mi corazón debería dejar de latir lo suficientemente pronto.",
  ui_story_5055_50551802_6_dialog_content = "Oye, escucho un sonido, el sonido de algo estallando...",
  ui_story_5055_50551802_7_dialog_content = "Son las burbujas de memoria estallando en mi cabeza.",
  ui_story_5055_50551802_8_dialog_content = "No más miedo, no más pena y no más dolor...",
  ui_story_5055_50551802_9_dialog_content = "¿Pero por qué? ¿Por qué las lágrimas no dejan de fluir?",
  ui_story_5055_50551802_10_dialog_content = "El dolor sordo en mi pecho... ¿Es por el poder que me abandona?",
  ui_story_5055_50551802_11_dialog_content = "¿O es a lo que llaman anhelo...?",
  ui_story_5055_50551802_12_dialog_content = "Hermano, Dawn... Al final, aún no logro recordar sus rostros.",
  ui_story_5055_50551802_13_dialog_content = "Pero te extraño mucho, y a los demás también...",
  ui_story_5055_50551802_14_dialog_content = "¿No crees que lloro porque no quiero dejarte? Estoy llorando porque...",
  ui_story_5055_50551802_15_dialog_content = "¡De alegría! Finalmente, los protegí a todos ustedes a mi manera!",
  ui_story_5055_50551802_16_dialog_content = "Mira, no me olvidé de la alegría. La alegría también trae lágrimas.",
  ui_story_5055_50551802_17_dialog_content = "Espero que todos se sientan felices por mí...",
  ui_story_5055_50551802_18_dialog_content = "Por fin, puedo irme sin dolor, tranquilamente, en silencio...",
  ui_story_5055_50551802_19_dialog_content = "Esta es la mejor manera que se me ocurre para corresponder a tu amor.",
  ui_story_5055_50551802_20_dialog_content = "...",
  ui_story_5055_50551802_21_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_5055_50551802_22_dialog_content = "¿Qué está pasando?",
  ui_story_5055_50551802_23_dialog_content = "<size=45><color=#e8d9bb>¡Retumbante!</color></size>",
  ui_story_5055_50551802_24_dialog_content = "EveTodo está desapareciendo, incluso mi poder, así que nada debería estar afectando esta realidad...",
  ui_story_5055_50551802_25_dialog_content = "A menos que...",
  ui_story_5055_50551802_26_dialog_content = "A menos que el verdadero yo esté muriendo.",
  ui_story_5055_50551802_27_dialog_content = "No intentes gastar tu esfuerzo tratando de salvarme, por favor...",
  ui_story_5055_50551802_28_dialog_content = "Simplemente suéltame...",
  ui_story_5055_50551802_29_dialog_content = "No, ¡todavía estás vivo y debes vivir!",
  ui_story_5055_50551802_30_dialog_content = "¿Quién es esta persona?",
  ui_story_5055_50551802_31_dialog_content = "¿No me recuerdas, Eve? Soy PlayerName. ¡Soy PlayerName!",
  ui_story_5055_50551802_32_dialog_content = "PlayerName? He oído la historia del Príncipe Pharming salvando a una princesa en coma... ¿Eres tú mi Príncipe Encantador?",
  ui_story_5055_50551802_33_dialog_content = "Pero no tienes que mencionar mi pasado, porque incluso yo sé...",
  ui_story_5055_50551802_34_dialog_content = "Alguien como yo no vale la pena salvar...",
  ui_story_5055_50551802_35_dialog_content = "¡Pero realmente necesitamos tu ayuda!",
  ui_story_5055_50551802_36_dialog_content = "¿Mi ayuda? ¿Qué puedo hacer?",
  ui_story_5055_50551802_37_dialog_content = "¡Puedes hacer más de lo que imaginaste!",
  ui_story_5055_50551802_38_dialog_content = "Pero mi poder es malvado e incontrolable. Destruiré todo...",
  ui_story_5055_50551802_39_dialog_content = "¡Ni el doctor ni los Eclipsites te obligaron a hacer eso!",
  ui_story_5055_50551802_40_dialog_content = "¡Es tu habilidad natural que ha estado latente dentro de ti!",
  ui_story_5055_50551802_41_dialog_content = "¡Es lo suficientemente fuerte para protegernos a todos!",
  ui_story_5055_50551802_42_dialog_content = "¡Recuerda la verdadera fuente de tu poder!",
  ui_story_5055_50551802_43_dialog_content = "Todos esperamos que vuelvas...",
  ui_story_5055_50551802_44_dialog_content = "<size=45>¡Despierta!</size>",
  ui_story_5055_50551802_45_dialog_content = "<size=45>¡Despierta!</size> ¡DESPIERTA! <size=30>Despierta...</size>",
  ui_story_5055_50551901_1_dialog_content = "...",
  ui_story_5055_50551901_2_dialog_content = "Entiendo... ¡Finalmente encontré la pieza perdida!",
  ui_story_5055_50551901_3_dialog_content = "Estas son las personas más importantes para mí...",
  ui_story_5055_50551901_4_dialog_content = "¡Ahora es el momento de unir los retratos de todos!",
  ui_story_5055_50551901_5_dialog_content = "¿Puede ser esto...",
  ui_story_5055_50551901_6_dialog_content = "Vaya, vale la pena intentarlo.",
  ui_story_5055_50551901_7_dialog_content = "...",
  ui_story_5055_50551901_8_dialog_content = "¡Hola, esto es...!",
  ui_story_5055_50551901_9_dialog_content = "Sinsa... Dawn... PlayerName...!",
  ui_story_5055_50551901_10_dialog_content = "¡Todas sus caras! Finalmente recuerdo cómo lucen todas.",
  ui_story_5055_50551901_11_dialog_content = "¿Qué está pasando, por qué no puedo controlar mis lágrimas hoy...",
  ui_story_5055_50551901_12_dialog_content = "Veo que en realidad quería ver a todos más de lo que creía.",
  ui_story_5055_50551901_13_dialog_content = "Pensé que había tomado la decisión de quedarme aquí de una vez por todas...",
  ui_story_5055_50551901_14_dialog_content = "No, tú querías salir, despertar y dar un paseo con tu mejor atuendo.",
  ui_story_5055_50551901_15_dialog_content = "Puedes visitar una pradera llena de flores o una exuberante selva tropical.",
  ui_story_5055_50551901_16_dialog_content = "Pensé que mi poder me había convertido en un monstruo que solo lastimaría a las personas...",
  ui_story_5055_50551901_17_dialog_content = "No, nos protegerás con tu poder.",
  ui_story_5055_50551901_18_dialog_content = "Mientras confíes en la persona en la que puedes convertirte. Su grandeza y gloria serán tu futuro.",
  ui_story_5055_50551901_19_dialog_content = "Pensé que si me alejaba de todos y estaba solo, no causaría problemas...",
  ui_story_5055_50551901_20_dialog_content = "No, nunca estuviste solo.",
  ui_story_5055_50551901_21_dialog_content = "EveTodos han estado aquí todo el tiempo.",
  ui_story_5055_50551901_22_dialog_content = "Eve!",
  ui_story_5055_50551901_23_dialog_content = "Eve.",
  ui_story_5055_50551901_24_dialog_content = "Eve, Eve, Eve...",
  ui_story_5055_50551901_25_dialog_content = "Eve!",
  ui_story_5055_50551901_26_dialog_content = "Hermano.",
  ui_story_5055_50551901_27_dialog_content = "Mi familia, mis amigos, mi anhelo por el mundo real...",
  ui_story_5055_50551901_28_dialog_content = "¡Lo estoy recuperando, recuperándolo todo!",
  ui_story_5055_50551901_29_dialog_content = "Pero el yo presente no está completo. He destruido partes de mí.",
  ui_story_5055_50551901_30_dialog_content = "No puedo salir y verte de nuevo...",
  ui_story_5055_50551901_31_dialog_content = "Sí, tú puedes. Siempre pudiste.",
  ui_story_5055_50551901_32_dialog_content = "¿Ah?",
  ui_story_5055_50551901_33_dialog_content = "¡Estás de vuelta! ¡Pensé que te habías ido por completo!",
  ui_story_5055_50551901_34_dialog_content = "Puedes sentir miedo de nuevo, ¿no puedes?",
  ui_story_5055_50551901_35_dialog_content = "Después de lo que te hice... Gracias por regresar a mí.",
  ui_story_5055_50551901_36_dialog_content = "Pero veo que nunca pude eliminar mi ansiedad y miedo.",
  ui_story_5055_50551901_37_dialog_content = "¿Debería estar agradecido por no poder conquistarlos?",
  ui_story_5055_50551901_38_dialog_content = "No solo tienes miedo de perder el control de tu poder, también temes muchas otras cosas.",
  ui_story_5055_50551901_39_dialog_content = "Insectos que muerden, aguijones afilados, lugares oscuros, hermano lastimado, nadie prestando atención a ti...",
  ui_story_5055_50551901_40_dialog_content = "¡Alto, simplemente alto! ¿Debes seguir adelante?",
  ui_story_5055_50551901_41_dialog_content = "Pero está bien. Eso te hace ser quien eres... El verdadero tú, el verdadero nosotros.",
  ui_story_5055_50551901_42_dialog_content = "Solo aquellos que entendieron el amor y tenían algo que amar podían sentir miedo y pena.",
  ui_story_5055_50551901_43_dialog_content = "El poder que tengo ahora proviene del amor en tu corazón.",
  ui_story_5055_50551901_44_dialog_content = "¿Te vas de nuevo?",
  ui_story_5055_50551901_45_dialog_content = "Soy tú. Soy parte de nosotros. Nunca me iré.",
  ui_story_5055_50551901_46_dialog_content = "Pero me convertiré en ti, transformándonos en mí y dándote la fuerza para avanzar.",
  ui_story_5055_50551901_47_dialog_content = "Podemos... ¿Puedo salir de aquí ahora?",
  ui_story_5055_50551901_48_dialog_content = "Sí. Despertaremos en el mundo real muy pronto.",
  ui_story_5055_50551901_49_dialog_content = "¡Tengo otra pregunta! PlayerName dijo que necesitaba mi ayuda.",
  ui_story_5055_50551901_50_dialog_content = "Tú conoces la realidad mejor que yo, así que dime cómo puedo ayudar después de despertar?",
  ui_story_5055_50551901_51_dialog_content = "Ya estás ayudando a controlar la tormenta. Pero hay una cosa que todos quieren de ti.",
  ui_story_5055_50551901_52_dialog_content = "Quieren que vivas una vida feliz y despreocupada.",
  ui_story_5055_50551901_53_dialog_content = "Está bien si eres inmaduro, no lo suficientemente fuerte o necesitas mucha práctica para dominar tu poder.",
  ui_story_5055_50551901_54_dialog_content = "La clave es perseverar y vivir.",
  ui_story_5055_50551901_55_dialog_content = "¡Despierta! Eve!",
  ui_story_5055_50551901_56_dialog_content = "Escucha, alguien te está esperando.",
  ui_story_5055_50551901_57_dialog_content = "Eso es PlayerName, hermano, Dawn y los chicos de Rediesel Wrench...",
  ui_story_5055_50551901_58_dialog_content = "¡Me necesitan!",
  ui_story_5055_50551901_59_dialog_content = "Tengo miedo de muchas cosas en la realidad allá afuera, ¡pero también hay muchas cosas que amo!",
  ui_story_5055_50551901_60_dialog_content = "El amor es mucho más precioso que el odio.",
  ui_story_5055_50551901_61_dialog_content = "Tengo personas que amo, lugares que amo, así que...",
  ui_story_5055_50551901_62_dialog_content = "¡Seguiré viviendo!",
  ui_story_5055_50551901_63_dialog_content = "Muy pronto, abriré mis ojos...",
  ui_story_5055_50551901_64_dialog_content = "Entonces tomaré mi primera respiración con todo lo que tengo y apreciaré mi vida.",
  ui_story_5055_50551901_65_dialog_content = "¡Viviré, así como aquellos que me aman!",
  ui_story_5055_50559901_1_dialog_content = "Esta pieza...",
  ui_story_5055_50559901_2_dialog_content = "<color=#e8d9bb>Parece que este trozo de papel fue arrancado de un libro de imágenes.</color>",
  ui_story_5055_50559901_3_dialog_content = "<color=#e8d9bb>Muestra vagamente la cabeza de una misteriosa mujer con un abrigo blanco.</color>",
  ui_story_5055_50559901_4_dialog_content = "¿No es esta la parte que falta en mi libro de imágenes! La forma encaja... pero ¿por qué el color parece desajustado...?",
  ui_story_5055_50559901_5_dialog_content = "Déjame ver qué hay en ello...",
  ui_story_5055_50559901_6_dialog_content = "¡Es mi médico!",
  ui_story_5055_50559901_7_dialog_content = "¡Es el buen doctor que me curó! Jeje, bueno, eso tiene mucho sentido.",
  ui_story_5055_50559901_8_dialog_content = "Después de todo, es gracias a ella que soy libre ahora. Debo haber querido agradecerle por darme un hogar tan feliz.",
  ui_story_5055_50559901_9_dialog_content = "Ahora que lo pienso, ni siquiera puedo recordar si alguna vez sonrió. Creo que ella era muy estricta o tenía una cualidad algo extraña en ella.",
  ui_story_5055_50559901_10_dialog_content = "Oye, ¿eso es lo que llaman... ironía?",
  ui_story_5055_50559901_11_dialog_content = "Pero siento que ella debe haberme sonreído al menos una vez...",
  ui_story_5055_50559901_12_dialog_content = "Eh, ¿por qué de repente se siente frío aquí en el desierto? ¡Debería ir a buscar las otras piezas mientras pueda!",
  ui_story_5055_50559901_13_dialog_content = "¡Solo espera hasta que encuentre a quien destrozó este libro de imágenes! ¡No puedo creer que realmente hayan arrancado la cara del doctor! ¿Qué les pasa?!",
  ui_story_5055_50559901_14_dialog_content = "Lo rompieron tanto que ni siquiera puedo volver a armarlo...",
  ui_story_5055_50559901_15_dialog_content = "Espera, ahora que miro bien esta rasgadura, parece que hay una fila de marcas de dientes aquí...",
  ui_story_5055_50559901_16_dialog_content = "¿Podría ser que no fuera la sombra sino algún tipo de bicho royendo esta pieza?",
  ui_story_5055_50559901_17_dialog_content = "Erm, pero si solo era un bicho, entonces lo dejaré caer. No puedo exactamente ir persiguiendo a un animal...",
  ui_story_5055_50559902_1_dialog_content = "<color=#e8d9bb>En el trozo de papel se encuentra la imagen de una maceta de cerámica que contiene un pequeño montículo de tierra.</color>",
  ui_story_5055_50559902_2_dialog_content = "Es un trozo de papel con una maceta vacía en él... ¡Es exactamente igual al que tengo en casa!",
  ui_story_5055_50559902_3_dialog_content = "Excepto que este está vacío... No hay nada creciendo en él.",
  ui_story_5055_50559902_4_dialog_content = "Si tan solo tuviera la semilla adecuada para ello...",
  ui_story_5055_50559902_5_dialog_content = "¿También fue arrancado este pedazo de papel de mi libro de imágenes?",
  ui_story_5055_50559902_6_dialog_content = "Parece que tiene el tamaño adecuado, pero la imagen está completamente equivocada.",
  ui_story_5055_50559902_7_dialog_content = "Debería ser el rostro de alguien importante para mí aquí...",
  ui_story_5055_50559902_8_dialog_content = "Pero no puedo recordar nada. ¡Mi cabeza está tan vacía como esta maceta!",
  ui_story_5055_50559902_9_dialog_content = "Olvidar a las personas más importantes para mí... es como una maceta sin sus flores.",
  ui_story_5055_50559902_10_dialog_content = "Todo lo que necesito hacer es pensar en una forma de encontrar lo que estoy buscando...",
  ui_story_5055_50559903_1_dialog_content = "<color=#e8d9bb>¡Una misteriosa criatura blanca!</color>",
  ui_story_5055_50559903_2_dialog_content = "Uh, ¿qué es esta cosa? ¡Nunca antes había visto un sapo blanco!",
  ui_story_5055_50559903_3_dialog_content = "¡Simplemente adoro los sapos, y uno blanco como este debe ser súper raro!",
  ui_story_5055_50559903_4_dialog_content = "Hmm... pero no parece tanto como un sapo, es tan pequeño y bonito. Maytal vez sea en realidad una rana...",
  ui_story_5055_50559903_5_dialog_content = "¡Vas por el camino equivocado, ranita, el lago está por ahí! Da vueltas en el desierto de Rediesel durante demasiado tiempo y es posible que te seques.",
  ui_story_5055_50559903_6_dialog_content = "Sé de otro lugar donde hay agua, si no te importa acompañarme...",
  ui_story_5055_50559903_7_dialog_content = "Honestamente, ¿por qué vendrías a un lugar tan seco y oscuro...?",
  ui_story_5055_50559903_8_dialog_content = "... Para encontrar... Eve...",
  ui_story_5055_50559903_9_dialog_content = "¡¿?!",
  ui_story_5055_50559903_10_dialog_content = "¿Escuché algo justo ahora... Fue mi imaginación?",
  ui_story_5055_50559904_1_dialog_content = "<color=#e8d9bb>Un juguete con una apariencia distintiva. Aunque su diseño básico parece bastante ordinario, lleva el sello de una artesanía exquisita.</color>",
  ui_story_5055_50559904_2_dialog_content = "Este juguete... parece ese perrito pelirrojo...",
  ui_story_5055_50559904_3_dialog_content = "... ¿Viniste aquí para unirte a mí en el lugar de ese perrito?",
  ui_story_5055_50559904_4_dialog_content = "Está un poco sucio, pero sostenerlo me hace sentir tan cálido por dentro, como abrazar a alguien cercano a mí...",
  ui_story_5055_50559904_5_dialog_content = "De repente siento un poco de nostalgia.",
  ui_story_5055_50559904_6_dialog_content = "Esto es extraño, ¿no está mi casa en algún lugar muy, muy cerca?",
  ui_story_5055_50559904_7_dialog_content = "Pero, ¿por qué extraño tanto a mi familia...?",
  ui_story_5055_50559904_8_dialog_content = "Extraño tener esos grandes y cálidos brazos rodeándome...",
  ui_story_5055_50559905_1_dialog_content = "<color=#e8d9bb>¡Un objeto dejado por la criatura blanca!</color>",
  ui_story_5055_50559905_2_dialog_content = "Creí que vi a una pequeña criatura pálida saltar frente a mí justo ahora...",
  ui_story_5055_50559905_3_dialog_content = "¿Dejó esto?",
  ui_story_5055_50559905_4_dialog_content = "¡Qué hermoso pequeño tesoro! Déjame ver, ¿es esta una diadema súper pequeña?",
  ui_story_5055_50559905_5_dialog_content = "Me parece algo familiar... ¿Dónde lo he visto antes...?",
  ui_story_5055_50559905_6_dialog_content = "... Estoy aquí... Eve...",
  ui_story_5055_50559905_7_dialog_content = "¡Realmente escuché algo! Pero parece que viene de un lugar tan extraño...",
  ui_story_5055_50559905_8_dialog_content = "Me gusta... como si alguien me llamara desde adentro...",
  ui_story_5055_50559906_1_dialog_content = "<color=#e8d9bb>Un trozo de papel con un patrón de llave inglesa colosal, que desprende un aire de poder y estilo.</color>",
  ui_story_5055_50559906_2_dialog_content = "... ¿Es este... otro de mis cuadros? Este parece una llave inglesa.",
  ui_story_5055_50559906_3_dialog_content = "Recuerdo cuando mi hermano me regaló mi primera brocha de pintura... Lo primero que me enseñó a pintar fue esta llave inglesa.",
  ui_story_5055_50559906_4_dialog_content = "Se enfadó tanto consigo mismo cuando su pintura no salió como quería, que arrugó la página enojado...",
  ui_story_5055_50559906_5_dialog_content = "Pero cuando pinté uno mejor que el suyo, él se veía tan orgulloso y dijo que no le sorprendía que pudiera hacerlo, ya que soy su hermana.",
  ui_story_5055_50559906_6_dialog_content = "...",
  ui_story_5055_50559906_7_dialog_content = "... Hermano...",
  ui_story_5055_50559907_1_dialog_content = "<color=#e8d9bb>Una semilla solitaria, como un voto solemne, espera ser descubierta en la esquina.</color>",
  ui_story_5055_50559907_2_dialog_content = "¿Es esto... una semilla de flor?!",
  ui_story_5055_50559907_3_dialog_content = "¡Recuerdo cómo se ven tus flores!",
  ui_story_5055_50559907_4_dialog_content = "Esta es tu semilla, ¿cierto? El pequeño amigo que perdí en el fuego...",
  ui_story_5055_50559907_5_dialog_content = "Gracias. Siempre estuviste ahí cuando más te necesité.",
  ui_story_5055_50559907_6_dialog_content = "¡Pero qué haces en un lugar como este?! ¡Te vas a quemar!",
  ui_story_5055_50559907_7_dialog_content = "¡Permíteme darte un nuevo hogar, un lugar donde pueda mantenerte a salvo! No dejaré que te pase nada malo, ¡lo prometo!",
  ui_story_5055_50559907_8_dialog_content = "Creo que, hace mucho tiempo, hice otra promesa...",
  ui_story_5055_50559907_9_dialog_content = "¡Tengo que recordar!",
  ui_story_5055_50559908_1_dialog_content = "<color=#e8d9bb>¡Ponle la pequeña diadema a la pequeña criatura blanca!</color>",
  ui_story_5055_50559908_2_dialog_content = "<color=#e8d9bb>La rana parece haber crecido después de colocarle la diadema y comienza a emitir un suave resplandor.</color>",
  ui_story_5055_50559908_3_dialog_content = "¡Es un ajuste perfecto! Podría ser solo un pequeño accesorio básico...",
  ui_story_5055_50559908_4_dialog_content = "Pero de alguna manera te hace parecer más refinado, como el príncipe rana en ese cuento de hadas del libro ilustrado.",
  ui_story_5055_50559908_5_dialog_content = "(¡Apuesto a que si lo visto correctamente, sería un príncipe tan guapo!)",
  ui_story_5055_50559908_6_dialog_content = "¡Oye, a dónde crees que vas?!",
  ui_story_5055_50559908_7_dialog_content = "¡No es seguro afuera! ¡No salgas!",
  ui_story_5055_50559908_8_dialog_content = "No te preocupes. Sé que nunca me lastimarías.",
  ui_story_5055_50559908_9_dialog_content = "¡¿Qué?!",
  ui_story_5055_50559908_10_dialog_content = "... Tu dificultad... tan difícil. ¡Permíteme hacer algo por ti también!",
  ui_story_5055_50559908_11_dialog_content = "¡Para que no tengas que pasar por todo esto solo!",
  ui_story_5055_50559909_1_dialog_content = "<color=#e8d9bb>¡El coloso de la pequeña criatura blanca!</color>",
  ui_story_5055_50559909_2_dialog_content = "Esto es... ¡Lo recuerdo! Vuela por el cielo, majestuoso y libre...",
  ui_story_5055_50559909_3_dialog_content = "¿Alguna vez he estado dentro de él?",
  ui_story_5055_50559909_4_dialog_content = "... Recuerdo una ventana brillante, con un vasto azul profundo afuera.",
  ui_story_5055_50559909_5_dialog_content = "Recuerdo a alguien dándome alimento y diciéndome palabras amables.",
  ui_story_5055_50559909_6_dialog_content = "Empecé a correr dentro de esto... Hacía mucho tiempo que no me sentía tan bien, y luego...",
  ui_story_5055_50559909_7_dialog_content = "Oh-",
  ui_story_5055_50559909_8_dialog_content = "Luego te embarcas en un viaje.",
  ui_story_5055_50559909_9_dialog_content = "Estás-?!",
  ui_story_5055_50559909_10_dialog_content = "Aunque enfrentaste muchas aventuras inesperadas en el camino, estabas decidido a cumplir una promesa importante.",
  ui_story_5055_50559909_11_dialog_content = "... Ahora, finalmente estás tan cerca de cumplir esa promesa, y hay muchas personas esperándote...",
  ui_story_5055_50559910_1_dialog_content = "<color=#e8d9bb>El juguete ve la llave inglesa en la pintura y salta a la página rasgada con entusiasmo desenfrenado.</color>",
  ui_story_5055_50559910_2_dialog_content = "<color=#e8d9bb>El juguete y la llave inglesa irradian una luz cálida, como el resplandor del sol de la mañana. Eve se frota los ojos y un rostro familiar aparece en la imagen.</color>",
  ui_story_5055_50559910_3_dialog_content = "¡Ahh! Es... ¡Es mi hermano!",
  ui_story_5055_50559910_4_dialog_content = "Por fin... ¡Por fin recuerdo la cara de mi hermano!",
  ui_story_5055_50559910_5_dialog_content = "... E... Eve!",
  ui_story_5055_50559910_6_dialog_content = "... ¡Es la voz de mi hermano! ¿De dónde viene...?",
  ui_story_5055_50559910_7_dialog_content = "Su ardiente deseo se ha manifestado. Aunque puedes escuchar su voz, él no puede sentir tu presencia.",
  ui_story_5055_50559910_8_dialog_content = "Eve!",
  ui_story_5055_50559910_9_dialog_content = "Lo siento por todo lo que pasó antes. No presté suficiente atención a cómo te sentías realmente... porque pensé que te estaba protegiendo, pero... no entendí cuánto dolor tenías...",
  ui_story_5055_50559910_10_dialog_content = "Soy un hermano terrible.",
  ui_story_5055_50559910_11_dialog_content = "No, hermano, fui tan terco. Yo sólo... ya no soporto cómo soy. Es por eso...",
  ui_story_5055_50559910_12_dialog_content = "Se acerca una tormenta, pero no te preocupes, te prometo que te protegeré.",
  ui_story_5055_50559910_13_dialog_content = "No... Sinsa, sólo corre, rápido...",
  ui_story_5055_50559910_14_dialog_content = "¡Haré un agujero en esta tormenta con mis manos y te sacaré de ahí! ¡Te llevo a casa!",
  ui_story_5055_50559910_15_dialog_content = "Entonces, si crees que puedes perdonarme algún día, simplemente despierta...",
  ui_story_5055_50559910_16_dialog_content = "... La casa está justo como la dejaste. Todas tus muñecas favoritas y tus pinturas te esperan en tu habitación...",
  ui_story_5055_50559910_17_dialog_content = "...",
  ui_story_5055_50559910_18_dialog_content = "Eve, realmente te extraño...",
  ui_story_5055_50559910_19_dialog_content = "... Sinsa... Yo también te extraño...",
  ui_story_5055_50559911_1_dialog_content = "<color=#e8d9bb>Una semilla de flor cae en la maceta vacía del libro ilustrado, y una flor del amanecer florece en la página.</color>",
  ui_story_5055_50559911_2_dialog_content = "<color=#e8d9bb>La flor florece con una luz brillante, tan deslumbrante como el amanecer. Eve se frota los ojos y un rostro familiar aparece en la página.</color>",
  ui_story_5055_50559911_3_dialog_content = "Dawn! Yo... ¡Lo recuerdo! Es el rostro de mi amigo, el que siempre ha estado ahí para mí... ¡Es Dawn!",
  ui_story_5055_50559911_4_dialog_content = "... Eve.",
  ui_story_5055_50559911_5_dialog_content = "... ¿De quién es esa voz? Dawn... ¡Dawn! ¿Eres tú?",
  ui_story_5055_50559911_6_dialog_content = "Su deseo ardiente se ha manifestado. Puedes escuchar su voz, pero tus palabras no pueden ser transmitidas a ella.",
  ui_story_5055_50559911_7_dialog_content = "... Eve...",
  ui_story_5055_50559911_8_dialog_content = "... Verte así... Me recuerda el día que nos conocimos...",
  ui_story_5055_50559911_9_dialog_content = "En esa enfermería fría, nuestros cuerpos estaban cubiertos de sensores y tubos...",
  ui_story_5055_50559911_10_dialog_content = "Yo... No soy tan confiable como pensabas...",
  ui_story_5055_50559911_11_dialog_content = "En la oscuridad y a través del miedo, todo lo que pude hacer fue apretar mis músculos y prepararme para el dolor... Por eso te ignoré en aquel entonces y por eso casi me malinterpretaste.",
  ui_story_5055_50559911_12_dialog_content = "No, tú ERES confiable, Dawn! Y eres la persona más valiente que conozco...",
  ui_story_5055_50559911_13_dialog_content = "Esa enfermería era como una jaula, y tú eras el único que se atrevió a desafiar a nuestro captor de frente.",
  ui_story_5055_50559911_14_dialog_content = "Fue poco después de eso que me di cuenta de que no eras malo en absoluto, simplemente te gusta mirar a las personas con esa mirada feroz en tu rostro.",
  ui_story_5055_50559911_15_dialog_content = "Completamente, absolutamente, no horrible.",
  ui_story_5055_50559911_16_dialog_content = "... Me encantaba escuchar tus historias. Tu voz, tus palabras... Llevaban la belleza del mundo que anhelaba ver y la mostraban ante mis ojos.",
  ui_story_5055_50559911_17_dialog_content = "...Aunque fue un poco incómodo cuando olvidaste lo que se suponía que debía venir después...",
  ui_story_5055_50559911_18_dialog_content = "Pero las historias en sí nunca fueron tan importantes como simplemente tenerte a mi lado...",
  ui_story_5055_50559911_19_dialog_content = "Le diste agua a la flor, me diste un nombre...",
  ui_story_5055_50559911_20_dialog_content = "Me gusta mucho este nombre... Dawn... Dawn...",
  ui_story_5055_50559911_21_dialog_content = "Entonces, necesitas despertarte pronto, ¿de acuerdo?",
  ui_story_5055_50559911_22_dialog_content = "Recuerda la promesa que hicimos: ver juntos el momento en que florece la flor del amanecer...",
  ui_story_5055_50559911_23_dialog_content = "Dawn, aún recuerdo... recuerdo todo... *sollozo* Fue terrible.",
  ui_story_5055_50559911_24_dialog_content = "Dawn sigue de pie allí en el campo de flores al amanecer esperando que yo la encuentre!",
  ui_story_5055_50559912_1_dialog_content = "<color=#e8d9bb>El príncipe rana blanco salta a la imagen y se sienta directamente en el coloso.</color>",
  ui_story_5055_50559912_2_dialog_content = "<color=#e8d9bb>Las alas blancas del Coloso se extienden en un arco, como una lluvia de meteoritos alcanzando el horizonte. Eve se frota los ojos y un rostro familiar aparece en la página.</color>",
  ui_story_5055_50559912_3_dialog_content = "¡Te conozco!",
  ui_story_5055_50559912_4_dialog_content = "Calle Tail, Eclipsites, Hermano, Dawn y las personas que enfrentaron estos recuerdos conmigo...",
  ui_story_5055_50559912_5_dialog_content = "PlayerName, ¡te recuerdo!",
  ui_story_5055_50559912_6_dialog_content = "Fuiste tú todo el tiempo, hablándome constantemente, impulsándome hacia adelante en este sueño con información del mundo exterior...",
  ui_story_5055_50559912_7_dialog_content = "Acompañándome mientras revisaba mi pasado para encontrar el dolor, la ira, el miedo dentro de mí...",
  ui_story_5055_50559912_8_dialog_content = "Even si todos están malditos en la parte más profunda de este sueño retorcido...",
  ui_story_5055_50559912_9_dialog_content = "Donde el hermano se convirtió en un perro grande, Dawn se convirtió en una flor, y una malvada bruja te convirtió en un pequeño sapo...",
  ui_story_5055_50559912_10_dialog_content = "¡Aún me encontraste! ¡No podías dejarme enfrentar esta pesadilla solo!",
  ui_story_5055_50559912_11_dialog_content = "Eres mi príncipe rana, ¿verdad?",
  ui_story_5055_50559912_12_dialog_content = "... Si eso es cierto, permíteme hacerte una pregunta.",
  ui_story_5055_50559912_13_dialog_content = "Tus caóticos recuerdos han sido calmados y la maldición de tu príncipe ha sido levantada.",
  ui_story_5055_50559912_14_dialog_content = "Seguramente la princesa también quiere liberarse de la maldición de la bruja y enfrentarse a su verdadero yo, ¿cierto?",
  ui_story_5055_50559912_15_dialog_content = "Mi verdadero yo...",
  ui_story_5055_50559912_16_dialog_content = "Dime, ¿qué es lo que más quieres ahora mismo?",
  ui_story_5055_50559912_17_dialog_content = "¡Quiero verte!",
  ui_story_5055_50559912_18_dialog_content = "Quiero ver a Dawn y a mi hermano! Quiero ver a Vice y a todos los que me han cuidado en Rediesel Wrench!",
  ui_story_5055_50559912_19_dialog_content = "Extraño mucho a todos ustedes... May aunque no ha pasado tanto tiempo para ustedes allá afuera.",
  ui_story_5055_50559912_20_dialog_content = "¡Pero siento que he estado solo aquí durante muchísimo tiempo!",
  ui_story_5055_50559912_21_dialog_content = "PlayerName, ¿puedes llevarme contigo de regreso?",
  ui_story_5055_50559912_22_dialog_content = "Tu fuerza te guiará de regreso.",
  ui_story_5055_50559912_23_dialog_content = "Espera... ¿Me estás dejando?",
  ui_story_5055_50559912_24_dialog_content = "(No lo olvides... tu amor.)"
}
return config
